      "path": "package.json",
      "content": "{\n  \"name\": \"dsh-wsl-browser\",\n  \"version\": \"0.1.0\",\n  \"description\": \"DeepSeek Harness tool: open http(s) URLs in the Windows default browser from WSL.\",\n  \"license\": \"MIT\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"https://github.com/173787247/dsh-wsl-browser.git\"\n  },\n  \"bugs\": {\n    \"url\": \"https://github.com/173787247/dsh-wsl-browser/issues\"\n  },\n  \"homepage\": \"https://github.com/173787247/dsh-wsl-browser#readme\",\n  \"type\": \"module\",\n  \"main\": \"index.js\",\n  \"engines\": { \"node\": \">=18\" },\n  \"scripts\": { \"test\": \"node --test test/browser.test.js\" },\n  \"files\": [\"index.js\", \"lib\", \"cordis.patch.yml\", \"README.md\", \"README.zh.md\", \"LICENSE\",\n    \"CHANGELOG.md\",\n    \"CONTRIBUTING.md\"],\n  \"keywords\": [\"dsh-plugin\", \"deepseek-harness\", \"wsl\", \"browser\"],\n  \"dsh\": { \"bundle\": { \"patch\": \"./cordis.patch.yml\" } }\n}\n"
    },
    {
      "path": "index.js",
      "content": "import { detectWsl, runPowerShell } from \"./lib/wsl-host.js\";\nimport {\n  buildOpenUrlScript,\n  formatBrowserResult,\n  isSafeHttpUrl,\n  rewriteLocalhostHint,\n} from \"./lib/browser.js\";\nimport { execFile } from \"node:child_process\";\nimport { promisify } from \"node:util\";\n\nconst execFileAsync = promisify(execFile);\n\nexport const name = \"dsh-wsl-browser\";\nexport const inject = [\"tools\", \"systemPrompt\"];\n\nexport function apply(ctx, config = {}) {\n  const timeoutMs = positive(config.timeoutMs, 15_000);\n  const wsl = detectWsl();\n\n  ctx.systemPrompt.section({\n    name: \"tool:win_open_url\",\n    order: 124,\n    text: \"Use win_open_url to open http(s) links in the Windows default browser (including 127.0.0.1 services started in WSL).\",\n  });\n\n  ctx.tools.register({\n    name: \"win_open_url\",\n    description: \"Open an http(s) URL in the Windows default browser from WSL.\",\n    parameters: {\n      type: \"object\",\n      additionalProperties: false,\n      required: [\"url\"],\n      properties: {\n        url: { type: \"string\", description: \"http or https URL.\" },\n      },\n    },\n    output: {\n      schema: {\n        type: \"object\",\n        additionalProperties: false,\n        properties: {\n          ok: { type: \"boolean\" },\n          href: { type: \"string\" },\n          note: { type: \"string\" },\n          error: { type: \"string\" },\n        },\n      },\n      render: (_args, value) => [{ type: \"text\", text: formatBrowserResult(value) }],\n    },\n    timeoutMs,\n    isConcurrencySafe: () => false,\n    async execute(args) {\n      if (!wsl) return { ok: false, error: \"not running in WSL\" };\n      const checked = isSafeHttpUrl(args?.url);\n      if (!checked.ok) return checked;\n      let wslIp = \"\";\n      try {\n        const { stdout } = await execFileAsync(\"hostname\", [\"-I\"], { encoding: \"utf8\", timeout: 3_000 });\n        wslIp = String(stdout || \"\").trim().split(/\\s+/)[0] || \"\";\n      } catch {\n        /* optional */\n      }\n      const hint = rewriteLocalhostHint(checked.href, wslIp);\n      try {\n        await runPowerShell(buildOpenUrlScript(checked.href), { timeoutMs });\n        return { ok: true, href: checked.href, note: hint.note };\n      } catch (err) {\n        return {\n          ok: false,\n          href: checked.href,\n          error: err instanceof Error ? err.message : String(err),\n          note: hint.note,\n        };\n      }\n    },\n    presentCall: () => ({ card: \"generic\", title: \"Open URL\" }),\n    presentResult: (_args, result) => (\n      result.isError\n        ? { card: \"generic\", title: \"Open URL failed\", content: result.content }\n        : { card: \"generic\", title: \"Open URL\", content: result.content }\n    ),\n  });\n}\n\nfunction positive(value, fallback) {\n  const n = Number(value);\n  return Number.isFinite(n) && n > 0 ? n : fallback;\n}\n"
    }
